export interface ComponentsRequest {
  readonly components: readonly string[];
}

export interface CoreOperators {
  /** Индекс ядра найден. `false` — сверять не с чем: имена правил идут в код как есть. */
  readonly found: boolean;
  /** Фабрики правил в порядке грамматики: по группам, внутри группы — по имени. */
  readonly rules: ReadonlyMap<string, CoreRule>;
  /** Значения из `./validators`, `./validation`, `./behaviors`: свой оператор так называться не может. */
  readonly names: ReadonlySet<string>;
  /**
   * Значения только из `./validation` и `./behaviors` — операторы схем и основа своих операторов.
   * По ним грамматика находит оператор ядра, которого нет в языке intent (ReFormer-wkva).
   */
  readonly operatorNames: ReadonlySet<string>;
}

export interface CoreRule {
  /** Имя фабрики: `minAge`. */
  name: string;
  /** Как записать правило в `rules`: `minAge(18)`, `required`. */
  call: string;
  /** Какие значения проверяет: `any`, `text`, `number`, `date`, `file` — или своё значение ядра. */
  group: string;
}

export interface DataSourceIntent {
  name: string;
  /** Комментарий-подсказка, откуда берутся значения. */
  note?: string;
  /**
   * Значения справочника — варианты поля выбора: `{ value, label }` либо примитивы (станут
   * `{ value: x, label: String(x) }`). Печатаются в `data-sources.ts`; без них справочник —
   * пустой массив с пометкой, и поле выбора рисуется без вариантов.
   */
  values?: unknown[];
}

export interface Dependency {
  target: string;
  reads: string[];
}

export interface DocumentCapabilities {
  /** Записи, которым в документе нет места. */
  readonly errors: JudgeFinding<'not-in-document'>[];
  /** Что форма не сохранит, хотя собирается. */
  readonly notes: JudgeFinding<'not-kept'>[];
}

export interface FieldIntent {
  /** Имя поля в модели. Оно же — `selector` узла, если не задан отдельно. */
  name: string;
  /** Путь в модели; по умолчанию совпадает с `name`. */
  modelPath?: string;
  type: FieldType;
  /** Имя компонента в реестре (`Input`, `Select`, …). */
  component: string;
  componentProps?: Record<string, unknown>;
  label?: string;
  initialValue?: unknown;
  /** Имя `$dataSource(...)` для полей выбора. */
  optionsSource?: string;
  /**
   * Имя `$dataSource(...)` подсказок поля со свободным вводом: значение остаётся текстом, подсказка
   * его только подставляет. Поле рисует `InputSuggest` (проп `suggestions`).
   */
  suggestionsSource?: string;
  /** Селектор узла для render-поведения; по умолчанию — `name`. */
  selector?: string;
}

export interface FormCatalogs {
  /** Компоненты кита. */
  readonly uiKit: UiKitComponents;
  /** Props-схемы компонентов кита — из того же каталога; без каталога `undefined`. */
  readonly uiKitProps?: UiKitPropSchemas;
  /** Фабрики правил и имена операторов ядра. */
  readonly core: CoreOperators;
}

export interface FormIntent {
  formName: string;
  /** Имя интерфейса модели, PascalCase. */
  interfaceName: string;
  target: ReformerTargetStack;
  layout: 'minimalist' | 'folders';
  layoutRoot: LayoutNode;
  /**
   * Именованные части разметки — подформы. Подключаются узлом `{ kind: 'part', ref, part }`.
   * Листья части ссылаются на поля относительно группы подключения. Строки массивов сюда не
   * входят: их часть генератор строит сам из `ArrayIntent.itemFields`.
   */
  parts?: Record<string, LayoutNode>;
  fields: FieldIntent[];
  arrays: ArrayIntent[];
  validation: ValidationRuleIntent[];
  behavior: BehaviorIntent[];
  /** Правила узлов схемы: события компонентов, эффекты рендера, хуки жизненного цикла. */
  nodes?: NodeRuleIntent[];
  visibility: VisibilityIntent[];
  dataSources: DataSourceIntent[];
  /**
   * Свои операторы: имя → модуль, из которого его импортирует сборка (`./operators` — файл
   * `operators.ts` каталога формы). Так подключаются свои правила (`rules`), свои операторы
   * валидации (`call` правила), свои операторы поведения (`kind: 'call'`) и функции, которые
   * читают выражения. Модулю каталога формы `form_build` пишет заготовку, пока её не правили.
   */
  operators?: Record<string, string>;
  wizard?: WizardIntent;
  /** Всё, чего не хватило для полного бандла, — видно потребителю. */
  warnings: string[];
}

export interface IntentGrammarOptions {
  /** По умолчанию — база. У профиля `document` секций нет: его текст один. */
  readonly sections?: GrammarRequest;
  /**
   * Для кого грамматика: `module` (по умолчанию) — `form.intent.json`, из которого `form_build`
   * пишет модуль; `document` — intent документа формы (ассистент конструктора, `build_form`): без
   * таргета, разметки JSX, начальных значений и того, что живёт только в коде модуля (`./document`).
   */
  readonly profile?: 'module' | 'document';
}

export interface IntentProblem {
  code: IntentProblemCode;
  /** Место в присланном объекте: `fields[2].name`. */
  at: string;
  /** Что не так. */
  message: string;
  /** Какой вид ожидается вместо этого. */
  expected: string;
}

export type IntentProblemCode =
  /** Вход — не объект intent: строка не JSON, массив, число. */
  | 'intent-unreadable'
  /** Запись списка — не объект: поле, массив, правило, поведение, видимость, шаг, узел. */
  | 'not-an-object'
  /** Нет обязательного: имени поля, цели правила, вида поведения, ссылки узла, тела обработчика. */
  | 'missing-key'
  /** Ключ, которого у записи нет; подсказка называет ближайший допустимый. */
  | 'unknown-key'
  /** Два синонима одного ключа с разными значениями либо описание на месте против объявления. */
  | 'key-conflict'
  /** Свойство, которого у компонента нет. */
  | 'prop-unsupported'
  /** Значение не того вида: `required` не логическое, параметр замечания — объект. */
  | 'invalid-value'
  /** Вид поведения, которого контракт не знает. */
  | 'unknown-kind'
  /** Второе объявление того же пути. */
  | 'duplicate'
  /** Связь, которая собралась бы и не сработала ни разу. */
  | 'inert-behavior';

export interface IntentReading {
  /** Нормализованный intent из того, что прочитать удалось. */
  intent: FormIntent;
  /** Выброшенные записи. Пусто — вход прочитан целиком. */
  problems: IntentProblem[];
  /** Предупреждения с кодами, в порядке `intent.warnings`. */
  notices: IntentWarning[];
}

export interface IntentVerdict {
  /** Ошибок нет: модуль собирается. */
  ok: boolean;
  /** Прочитанный intent — и при ошибках: потребитель показывает, что из него понято. */
  intent: FormIntent;
  errors: JudgeFinding[];
  warnings: JudgeFinding<JudgeWarningCode>[];
  /** Сборка модуля: файлы, их заметки и схема. Есть, когда судили модуль и intent прочитан. */
  bundle?: ReturnType<typeof buildBundle>;
}

export interface IntentWarning {
  code: IntentWarningCode;
  /** Текст, тот же, что в `FormIntent.warnings`. */
  message: string;
  /** Место в присланном объекте (`fields[2]`) или имя сущности, когда оно есть. */
  at?: string;
}

export type JudgeCode =
  | IntentProblemCode
  | CrossCheckCode
  /** Поле или массив объявлены, но не стоят в раскладке: модель их знает, пользователь не увидит. */
  | 'unplaced'
  /** У кода замечания нет своего текста либо их два. */
  | 'lost-message'
  /** Компонента нет в ките. */
  | 'unknown-component'
  /** Окружение не даёт собрать модуль: нет индекса ядра или каталога кита. */
  | 'environment'
  /** Правило, которое выбранный таргет не исполняет: видимость и правила узлов на core. */
  | 'not-on-target'
  /** Записи, которым в документе формы нет места: код модуля (`./document`). */
  | 'not-in-document';

export interface JudgeFinding<C extends string = JudgeCode> {
  code: C;
  message: string;
  /** Место в intent (`fields[2].lable`), когда оно известно. */
  at?: string;
  /** Что сделать либо что ожидается. */
  hint?: string;
}

export function judgeIntent(
  raw: unknown,
  catalogs: FormCatalogs,
  options: JudgeOptions = {}
): IntentVerdict

export interface JudgeOptions {
  /**
   * Судить документ билдера, а не модуль: без требований к окружению модуля, без правил таргета и
   * без заметок о печати модуля.
   */
  forDocument?: boolean;
  /** Схема, присланная на сверку (`validate_form`). Без неё — схема, собранная из intent. */
  schema?: unknown;
  /** Ключи реестра компонентов — для сверки присланной схемы (C2). */
  componentNames?: string[];
  /** Ключи реестра справочников. */
  dataSourceNames?: string[];
  /**
   * Есть ли у сервера `form_build` (по умолчанию — да). В воркере конструктора его нет: подсказки
   * ведут в справочные инструменты, а не в грамматику `form_build` (ReFormer-11oe.6).
   */
  formBuild?: boolean;
  /**
   * Требовать окружение модуля: индекс ядра и каталог кита (по умолчанию — да). `validate_form` модуль
   * не собирает и без них лишь не сверяет имена — об этом он говорит сам.
   */
  requireEnvironment?: boolean;
}

export type JudgeWarningCode =
  | IntentWarningCode
  | CrossCheckCode
  | 'module-note'
  | 'component-props'
  /** Документ формы этого не сохранит: начальные значения, справочник без значений. */
  | 'not-kept';

export interface Knowledge {
  /** Слитый индекс всех пакетов, у которых он есть. */
  readonly index: MergedIndex;
  /** Документация: `llms.txt` и его секции. */
  readonly docs: DocsCorpus;
  /** Файлы `docs/llms`; в средах без них — {@link EMPTY_RECIPE_SOURCE}. */
  readonly recipes: RecipeSource;
  /** Спеки; в средах без них — {@link EMPTY_SPEC_SOURCE}. */
  readonly spec: SpecSource;
  /** Сток отчётов; в средах без записи — {@link UNAVAILABLE_ISSUE_SINK}. */
  readonly issues: IssueSink;
  /** Каталоги форм; в средах без записи — {@link UNAVAILABLE_FORM_WORKSPACE}. */
  readonly forms: FormWorkspace;
  /** См. {@link SymbolsFallback}. */
  readonly symbolsFallback?: SymbolsFallback;
  /** См. {@link UiKitCatalogSource}. */
  readonly uiKitCatalog?: UiKitCatalogSource;
  /** См. {@link PlatformStatusSource}. */
  readonly status?: PlatformStatusSource;
  /**
   * Ленивые производные, общие на экземпляр: разобранные символы фолбэка, поисковые корпуса.
   *
   * Именно на экземпляр, а не на модуль. Модульный кэш был бы общим для двух разных Knowledge
   * (например, вшитого артефакта и папки проекта), и второй молча отвечал бы данными первого.
   */
  readonly memo: Map<string, unknown>;
}

export interface KnowledgeSources {
  docs: DocsSource;
  index: IndexSource;
  /**
   * Исходные файлы `docs/llms`. Отсутствует — первая стадия `find_recipe` (подбор по имени
   * файла) отключается, топик уходит в каскад по секциям `llms.txt`.
   */
  recipes?: RecipeSource;
  /** Текст постановки задачи. Отсутствует — `plan_form` работает только от `description`. */
  spec?: SpecSource;
  /** Куда сохранять отчёты `report_issue`. Отсутствует — инструмент честно откажет. */
  issues?: IssueSink;
  /** Куда `form_build` записывает модуль формы. Отсутствует — инструмент откажет. */
  forms?: FormWorkspace;
  /** Отсутствует — пакеты без индекса просто не дадут символов. */
  symbolsFallback?: SymbolsFallback;
  /** Отсутствует — генератор работает без каталога кита: имена компонентов не сверяются. */
  uiKitCatalog?: UiKitCatalogSource;
  /** Что знает о себе платформа — для `reformer://status`. Отсутствует — ресурса нет. */
  status?: PlatformStatusSource;
}

export type LayoutNode =
  | { kind: 'field'; ref: string }
  // `selector` у массива — точка адресации для behavior/visibility. Без него генератор
  // подставлял имя массива, и правило, ссылавшееся на собственный selector из intent,
  // адресовало узел, которого в разметке нет.
  | { kind: 'array'; ref: string; selector?: string }
  // Подформа: именованная часть (`FormIntent.parts`), подключённая к группе модели. `ref` — путь
  // группы в области узла. Листья части ссылаются на поля ОТНОСИТЕЛЬНО группы (`city`, а не
  // `registrationAddress.city`), поэтому одна часть подключается к нескольким группам.
  | { kind: 'part'; ref: string; part: string; selector?: string }
  | {
      kind: 'container';
      component: string;
      htmlTag?: string;
      componentProps?: Record<string, unknown>;
      selector?: string;
      children: LayoutNode[];
    }
  | { kind: 'step'; title: string; icon?: string; selector?: string; children: LayoutNode[] }
  // Текст среди детей: заголовок, абзац, подпись кнопки — страница, а не только форма. Строка в
  // `children` — ссылка на поле, поэтому текст — запись `{ "text": … }` (ReFormer-11oe.16).
  | { kind: 'text'; text: string };

export interface NodeRuleIntent {
  kind: NodeBehaviorKind;
  /** Узел схемы. У `renderEffect` его нет: эффект живёт, пока смонтирована схема. */
  selector?: string;
  /** Проп-событие компонента у `onComponentEvent`: `onSubmit`, `onChange`, … */
  event?: string;
  /**
   * Тело обработчика на TS — вставляется как есть. `await` делает обработчик асинхронным; у
   * `onComponentEvent` аргументы события — `args`, у `onMount` и `renderEffect` тело может
   * вернуть очистку: `return () => clearInterval(timer);`.
   */
  expr: string;
}

export function normalizeFieldComponent(
  component: string,
  fieldType: string,
  props: Record<string, unknown> = {},
  kit: UiKitComponents = NO_UI_KIT
): NormalizedFieldComponent

symbols.description:
Привести компонент поля к актуальному registry-имени.

- имя экспорта (`CheckboxWithLabel`) → registry-имя (по каталогу кита);
- `Input` для числового поля или с `type: 'number'` → `InputNumber` (у `Input` больше нет
  `type: 'number'`: схема `additionalProperties: false`, а значение ушло бы в модель строкой);
- `Input` с `suggestions` → `InputSuggest`;
- `FileUpload` с `variant: 'dropzone' | 'input'` → `FileUploadDropzone` / `FileUploadInput`
  (пропа `variant` у `FileUpload*` больше нет).

